<script setup lang="ts">import { useQuery } from '@tanstack/vue-query';import { adminApi } from '../api';import DsBadge from '@/shared/ui/DsBadge.vue';import DsButton from '@/shared/ui/DsButton.vue';import DsCard from '@/shared/ui/DsCard.vue';import DsPageHeader from '@/shared/ui/DsPageHeader.vue';import DsState from '@/shared/ui/DsState.vue';const q=useQuery({queryKey:['admin','users'],queryFn:adminApi.users})</script><template><section><DsPageHeader eyebrow="ACCESS CONTROL" title="User Management" description="Manage people and their role assignments."><template #actions><DsButton disabled>Add user</DsButton></template></DsPageHeader><DsCard class="panel"><DsState v-if="q.isPending.value" kind="loading"/><DsState v-else-if="q.isError.value" kind="error" title="Unable to load users"/><DsState v-else-if="!q.data.value?.length" kind="empty" title="No users yet"/><table v-else><thead><tr><th>Name</th><th>Email</th><th>Status</th><th>Roles</th></tr></thead><tbody><tr v-for="u in q.data.value" :key="u.PublicID"><td><strong>{{u.Name}}</strong></td><td>{{u.Email}}</td><td><DsBadge :tone="u.Status==='active'?'success':'neutral'">{{u.Status}}</DsBadge></td><td>{{u.Roles?.join(', ')||'—'}}</td></tr></tbody></table></DsCard></section></template><style scoped>section{padding:32px}.panel{padding:0;overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:15px 18px;border-bottom:1px solid var(--ds-border);font-size:14px}th{color:var(--ds-text-muted);font-size:12px;text-transform:uppercase;letter-spacing:.05em}tbody tr:last-child td{border-bottom:0}@media(max-width:640px){section{padding:20px}}</style>